input.old_string:
sig = self.fh.read(4)
if sig == b'\x1A\x41\x12\x43':
    self.endian = '<'
elif sig == b'\x43\x12\x41\x1A':
    self.endian = '>'
else:
    raise ValueError(f"Not a 2bit file: {sig}")

